import { describe, expect, it } from "vitest";
import { computeSlots } from "./availability";
import golden from "./single-service-golden.json";
import { describeSlots, GOLDEN_CASES } from "./single-service-golden.fixture";

/**
 * Regression guard for M6.8 (multi-service chains): a single service is a chain of one and must
 * give exactly the slots and options the pre-chain engine gave. `single-service-golden.json` was
 * generated by running `GOLDEN_CASES` through `computeSlots` at the merge base (1ea48fd) — buffers,
 * breaks, busy time, time off, special hours, lead time, "any staff" ranking, resource units and
 * both Europe/Warsaw DST transitions. Never regenerate it from this branch's engine: a diff here is
 * a behaviour change for every single-service booking.
 */
describe("single service: same slots as before multi-service chains (golden)", () => {
  for (const [name, mk] of Object.entries(GOLDEN_CASES)) {
    it(`${name}: identical slots, options and unit picks`, () => {
      const input = mk();
      const slots = computeSlots(input);
      expect(describeSlots(slots, input.timeZone)).toEqual(
        (golden as Record<string, string[]>)[name],
      );
    });

    it(`${name}: each option is one line equal to the option itself`, () => {
      const input = mk();
      for (const slot of computeSlots(input)) {
        for (const o of slot.options) {
          expect(o.lines, `slot ${new Date(slot.start).toISOString()} staff ${o.staffId}`).toEqual([
            {
              staffId: o.staffId,
              start: o.start,
              end: o.end,
              occupancy: o.occupancy,
              unitIds: o.unitIds,
            },
          ]);
        }
      }
    });
  }
});
